// All IDs, credentials, evidence and operational confirmations here are SYNTHETIC ONLY.
function medicinePilotInput(array $f,string $id,string $last='0'):array {
    return medicineGovernanceInput($f[0],$f[4],'chemical',$id,['expected_enrollment_event_id'=>$last,'rationale'=>'SYNTHETIC ONLY operator enrollment']);
}
function medicinePilotApproved():array {
    $f=medicineV1Fixture();$id=$f[5]->registerChemicalReference(['substance_id'=>'2'])['chemical_ref_id'];medicineV1Verify($f,$id);return [$f,$id];
}
function medicinePilotManifest(array $f,array $ids):void {
    [$r,$s,$a,$auth,$e,$i,$p]=$f;$entries=[];$a->actorId=8;
    foreach($ids as $id){$result=$s->enrollPilot('chemical',$id,medicinePilotInput($f,$id));$entries[]=['scope'=>'chemical','target_id'=>$id,'revision'=>(string)$result['revision'],'approval_event_id'=>(string)$result['approval_event_id'],'enrollment_event_id'=>(string)$result['event_id']];}
    $p->configuration['pilot_internal_enabled']=true;
    $p->configuration['pilot_activation']=['pilot_code'=>'synthetic_v1','administrator_id'=>8,'deployment_operator_id'=>8,'reviewer_id'=>2,'backup_reference'=>'SYNTHETIC_ONLY_BACKUP','deployment_reference'=>'SYNTHETIC_ONLY_DEPLOYMENT','public_disabled'=>true,'enrollments'=>$entries];
}
function medicinePilotActiveFixture():array {
    $f=medicineV1Fixture();[$r,$s,$a,$auth,$e,$i,$p]=$f;$ids=[];
    foreach(['2','10','20','21','22'] as $sid){
        if(!isset($r->inner->data['substances'][$sid])){$r->inner->data['substances'][$sid]=['substance_id'=>$sid,'is_active'=>1];$p->configuration['pilot_substances'][]=['substance_id'=>$sid,'unambiguous'=>true,'representative_reference'=>'SYNTHETIC_ENTITY_'.$sid];}
        $a->actorId=1;$id=$i->registerChemicalReference(['substance_id'=>$sid])['chemical_ref_id'];medicineV1Verify($f,$id);$ids[]=$id;
    }
    medicinePilotManifest($f,$ids);return [$f,$ids];
}
if(defined('MEDICINE_PILOT_LIBRARY')){return;}

medicineTest('candidate intake cannot be mistaken for approved enrollment',function(){ $f=medicineV1Fixture();$id=$f[5]->registerChemicalReference(['substance_id'=>'2'])['chemical_ref_id'];$f[2]->actorId=8;medicineReject(fn()=>$f[1]->enrollPilot('chemical',$id,medicinePilotInput($f,$id)),409);medicineCheck($f[0]->latest('chemical',$id)['action']==='create');});
foreach([1,2,4,6,7,0] as $actor){medicineTest('ordinary reviewer editor inactive anonymous enrollment denied '.$actor,function()use($actor){[$f,$id]=medicinePilotApproved();$before=$f[0]->eventRows;$f[2]->actorId=$actor;medicineReject(fn()=>$f[1]->enrollPilot('chemical',$id,medicinePilotInput($f,$id)),403);medicineCheck($before===$f[0]->eventRows);});}
medicineTest('operator enrollment preserves current approval and records actual actor revision reason code',function(){[$f,$id]=medicinePilotApproved();[$r,$s,$a,$auth,$e]=$f;$approval=$r->latest('chemical',$id);$a->actorId=8;$out=$s->enrollPilot('chemical',$id,medicinePilotInput($f,$id));$event=$r->event($out['event_id']);medicineCheck($event['actor_id']===8&&$event['revision']===(int)$approval['revision']&&$event['occurred_at']!==''&&$event['rationale']!=='');medicineCheck(json_decode($event['snapshot_json'],true)['pilot_code']==='synthetic_v1');medicineCheck($r->event((string)$approval['id'])===$approval&&$out['published']===false);$e->requireCurrent('chemical',$id);medicineCheck($e->decision('chemical',$id)===$approval);medicineReject(fn()=>$s->enrollPilot('chemical',$id,medicinePilotInput($f,$id)),409);});
medicineTest('stale and foreign enrollment input denied without actor injection',function(){[$f,$id]=medicinePilotApproved();$f[2]->actorId=8;$input=medicinePilotInput($f,$id);$input['expected_revision']='1';medicineReject(fn()=>$f[1]->enrollPilot('chemical',$id,$input),409);$input=medicinePilotInput($f,$id);$input['actor_id']=8;medicineReject(fn()=>$f[1]->enrollPilot('chemical',$id,$input),422);medicineReject(fn()=>$f[1]->enrollPilot('chemical','1 OR 1=1',$input),422);medicineReject(fn()=>$f[1]->enrollPilot('grant',$id,$input),422);});
medicineTest('missing retracted evidence denies otherwise approved enrollment',function(){[$f,$id]=medicinePilotApproved();$f[2]->actorId=8;$input=medicinePilotInput($f,$id);$f[6]->configuration['evidence_sources']['SYNTHETIC_TEST_ONLY']['active']=false;medicineReject(fn()=>$f[1]->enrollPilot('chemical',$id,$input),403);});
medicineTest('revoked professional authority denies enrollment',function(){[$f,$id]=medicinePilotApproved();$f[0]->grantRows['3']['is_active']=0;$f[2]->actorId=8;medicineReject(fn()=>$f[1]->enrollPilot('chemical',$id,medicinePilotInput($f,$id)),409);});
medicineTest('enrollment journal storage fault rolls back without destroying approval',function(){[$f,$id]=medicinePilotApproved();$before=$f[0]->eventRows;$f[0]->fault=true;$f[2]->actorId=8;medicineReject(fn()=>$f[1]->enrollPilot('chemical',$id,medicinePilotInput($f,$id)),503);medicineCheck($before===$f[0]->eventRows);$f[4]->requireCurrent('chemical',$id);});
medicineTest('five explicit approvals enroll and expose minimal internal projection only',function(){[$f,$ids]=medicinePilotActiveFixture();$f[2]->actorId=1;$out=$f[1]->internalPilot('chemical',$ids[0]);medicineCheck($out['internal']===true&&$out['published']===false&&$out['target_id']===$ids[0]);medicineCheck(array_keys($out)===['scope','target_id','revision','display_name','internal','published']);medicineCheck(!str_contains(json_encode($out),'SYNTHETIC_ONLY')&&!isset($out['history']));$f[2]->actorId=2;$f[1]->internalPilot('chemical',$ids[0]);medicineCheck(true);});
foreach(['off','backup','deployment','administrator','operator','reviewer','public','manifest','code','small','stale'] as $bad){medicineTest('activation gate rejects '.$bad,function()use($bad){[$f,$ids]=medicinePilotActiveFixture();$p=$f[6];$g=&$p->configuration['pilot_activation'];switch($bad){case 'off':$p->configuration['pilot_internal_enabled']=false;break;case 'backup':$g['backup_reference']='';break;case 'deployment':$g['deployment_reference']='';break;case 'administrator':$g['administrator_id']=1;break;case 'operator':$g['deployment_operator_id']=2;break;case 'reviewer':$g['reviewer_id']=1;break;case 'public':$g['public_disabled']=false;break;case 'manifest':$g['enrollments'][1]=$g['enrollments'][0];break;case 'code':$g['pilot_code']='other';break;case 'small':array_pop($g['enrollments']);break;case 'stale':$g['enrollments'][0]['revision']='1';}$f[2]->actorId=1;medicineReject(fn()=>$f[1]->internalPilot('chemical',$ids[0]),$bad==='stale'?409:403);});}
